head.script:
// 화면 리사이징

scwin.gLdMktTp = js_market;
scwin.gEmpNo = js_emp_no;
scwin.gIsurCd;
scwin.threadID;
scwin.procJob;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.init();
        await scwin.reloadAuto();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10920.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.reloadAuto();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10920.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnFail
 * @description MASTER On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnFail = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10920.dts_MASTER_OnFail" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10920.dts_MASTER_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {
            dts_MASTER.removeAll();
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10920.dts_MASTER_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    try {
        scwin.setContnId(row);
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10920.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10920.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10920.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10920.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
