///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '4' || scwin.gLdMktTp === '6') {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        panel_mkt.hide();
    } else {
        rdo_MKT_ID.setValue('9');
    }
    if (scwin.gLdMktTp === '1') {
        panel_jongmok.style.visibility = "";
    }

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    // edt_FromDate.text = cGetMinusDate2(vCurDate, 365);     // 일주일전 날짜
    edt_FromDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 발행회사
    const sbmOptions = {
        id : "sbm_dts_CompanyList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_CompanyList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_Jongmok",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_Jongmok=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&LD_MKT_TP=" + rdo_MKT_ID.getValue();
    url += "&SDATE=" + edt_FromDate.getValue();
    url += "&EDATE=" + edt_ToDate.getValue();
    url += "&ISUR_CD=" + (txb_isur_cd.getValue() === '' ? cmb_Company.getValue() : txb_isur_cd.getValue());
    url += "&ISU_CD=" + cmb_Jongmok.getValue();
    url += "&SCREN_ID=" + "ULDSTF10920.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/MktActNotice.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description 선택한 항목이 있는지 check
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 선택한 항목이 있는지 check
    if (await scwin.check() === true) {
        await scwin.setHeader();
        let gCnt = 0;
        dts_UpdateList.setBroadcast(false);
        for (let i = 1, k = 1; i <= dts_MASTER.getRowCount(); i++) {
            if (dts_MASTER.getCellData(i, "CHECK") === "T") {
                dts_UpdateList.insertRow();
                dts_UpdateList.setCellData(k, "ISUR_CD", dts_MASTER.getCellData(i, "ISUR_CD"));
                dts_UpdateList.setCellData(k, "ISU_CD", dts_MASTER.getCellData(i, "ISU_CD"));
                dts_UpdateList.setCellData(k, "REQ_DDTM", dts_MASTER.getCellData(i, "REQ_DDTM"));
                dts_UpdateList.setCellData(k, "TRANSTR_EMP_NO", scwin.gEmpNo);
                k++;
                gCnt++;
            }
        }
        dts_UpdateList.setBroadcast(true, true);

        // if (! window.confirm(getMessageParam("MSG-A006", '총 '+gCnt+'건을 저장')) )   return;
        if (!window.confirm("(주의)공시배포 차단을 강제 해제합니다.")) return;
        scwin.procJob = "공시배포 차단내역 강제 해제";
        trs_save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/MktActNotice.do",
            ref : "dts_UpdateList",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

