///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_MASTER.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name check
 * @description check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check = async function() {
    let checkCnt = 0;
    for (let i = 1; i <= dts_MASTER.getRowCount(); i++) {
        if (dts_MASTER.getCellData(i, "CHECK") === "T") {
            checkCnt++;
        }
    }
    if (checkCnt <= 0) {
        await $c.win.alert("선택한 항목이 없습니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name reloadAuto
 * @description reload Auto 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reloadAuto = async function() {
    scwin.stopReload();

    // threadID = setInterval('fn_list_sync()',10000);   //10초
    await scwin.listSync();
};

/**
 * @method
 * @name stopReload
 * @description stop Reload 처리
 * @returns {void}
 * @hidden N
 */
scwin.stopReload = function() {
    clearInterval(scwin.threadID);
};

/**
 * @method
